import{_ as e,C as o,o as d,c as n,j as a,a as l,E as s,a3 as i}from"./chunks/framework.CZBGEXos.js";const q=JSON.parse('{"title":"Analyzer","description":"","frontmatter":{},"headers":[],"relativePath":"uk/tools/analyzer.md","filePath":"uk/tools/analyzer.md"}'),h={name:"uk/tools/analyzer.md"};function c(p,t,b,u,g,m){const r=o("Screenshot");return d(),n("div",null,[t[0]||(t[0]=a("h1",{id:"analyzer",tabindex:"-1"},[l("Analyzer "),a("a",{class:"header-anchor",href:"#analyzer","aria-label":'Permalink to "Analyzer"'},"​")],-1)),t[1]||(t[1]=a("p",null,"Analyzer — це робочий простір для графіків: один тікер, кілька таймфреймів поруч, на обраній вами біржі. Це єдиний інструмент, де можна малювати на графіках.",-1)),s(r,{src:"analyzer",alt:"Вікно Analyzer із чотирма графіками, списком тікерів і списком спостереження",caption:"Вікно Analyzer"}),t[2]||(t[2]=i('<p>На відміну від інших інструментів, Analyzer майже нічого не налаштовує в головному вікні — усе керується з самого вікна, а ваша розкладка запам&#39;ятовується між сеансами.</p><h2 id="розкладка" tabindex="-1">Розкладка <a class="header-anchor" href="#розкладка" aria-label="Permalink to &quot;Розкладка&quot;">​</a></h2><p>Вікно складається з двох частин: панель списків ліворуч із <strong>Markets</strong> і <strong>Watchlist</strong>, та область графіків праворуч.</p><h2 id="що-виводити-на-графік" tabindex="-1">Що виводити на графік <a class="header-anchor" href="#що-виводити-на-графік" aria-label="Permalink to &quot;Що виводити на графік&quot;">​</a></h2><h3 id="біржа" tabindex="-1">Біржа <a class="header-anchor" href="#біржа" aria-label="Permalink to &quot;Біржа&quot;">​</a></h3><p>П&#39;ять кнопок бірж: <strong>Bybit</strong>, <strong>Binance</strong>, <strong>Gate</strong> (Gate.io), <strong>OKX</strong> і <strong>Hyper</strong> (Hyperliquid). Перемикання біржі перезавантажує список тікерів і переводить усі графіки на нову біржу без перезавантаження вікна.</p><p>Рисунки зберігаються для кожного символу <em>і</em> для кожної біржі, тож той самий тікер на двох біржах має два окремі набори рисунків.</p><h3 id="тип-ринку" tabindex="-1">Тип ринку <a class="header-anchor" href="#тип-ринку" aria-label="Permalink to &quot;Тип ринку&quot;">​</a></h3><p><strong>FUT</strong> (безстрокові ф&#39;ючерси) або <strong>SPOT</strong>. Це змінює, які ринки показані і які метрики існують — див. <a href="#колонки-метрик">Колонки метрик</a>.</p><p>Перемикання на SPOT скидає активну метрику на 24H%, бо спотові ринки не мають відкритого інтересу й ставки фінансування.</p><h3 id="пошук" tabindex="-1">Пошук <a class="header-anchor" href="#пошук" aria-label="Permalink to &quot;Пошук&quot;">​</a></h3><p>Поле пошуку фільтрує список тікерів і навмисно поблажливе:</p><ul><li>Розділові знаки, пробіли, дефіси та скісні риски ігноруються.</li><li>Запити від трьох символів витримують пропущену або помилково набрану літеру.</li><li><strong>Кирилиця транслітерується за розташуванням клавіш.</strong> Набравши <code>ИЕСГІВЕ</code> з увімкненою українською розкладкою, ви знайдете <code>BTCUSDT</code>, бо це ті самі фізичні клавіші. Перемикати розкладку для пошуку не потрібно.</li></ul><h3 id="колонки-метрик" tabindex="-1">Колонки метрик <a class="header-anchor" href="#колонки-метрик" aria-label="Permalink to &quot;Колонки метрик&quot;">​</a></h3><p>Список показує колонку символу плюс одну або кілька колонок метрик:</p><table tabindex="0"><thead><tr><th>Колонка</th><th>Значення</th><th>Ринки</th></tr></thead><tbody><tr><td><strong>24H%</strong></td><td>Зміна ціни за 24 години</td><td>Ф&#39;ючерси та спот</td></tr><tr><td><strong>VOL</strong></td><td>Обсяг торгів за 24 години в доларах</td><td>Ф&#39;ючерси та спот</td></tr><tr><td><strong>OI</strong></td><td>Відкритий інтерес — сумарні відкриті позиції в доларах</td><td>Лише ф&#39;ючерси</td></tr><tr><td><strong>FR</strong></td><td>Ставка фінансування</td><td>Лише ф&#39;ючерси</td></tr></tbody></table><p>Клацніть заголовок колонки, щоб відсортувати за нею; клацніть ще раз, щоб змінити напрям. Активне сортування позначене стрілкою.</p><p>Скільки колонок видно, <strong>залежить від ширини панелі</strong>. Звузьте панель — і лишиться лише активна метрика; розширте — і колонки повертатимуться по одній. Markets і Watchlist вимірюються окремо, тож одночасно можуть показувати різну кількість колонок.</p><h3 id="список-спостереження" tabindex="-1">Список спостереження <a class="header-anchor" href="#список-спостереження" aria-label="Permalink to &quot;Список спостереження&quot;">​</a></h3><p>Додайте тікер зі списку Markets кнопкою <strong>+</strong>; приберіть зі списку спостереження кнопкою <strong>×</strong>. Кожен запис показує логотипи бірж, де він торгується — при наведенні видно <code>Listed on &lt;біржа&gt;</code>.</p><p>Значки лістингу відповідають <strong>поточному типу ринку</strong>: токен, який торгується лише на споті, не матиме значка, поки ви у ф&#39;ючерсах.</p><p>Список спостереження зберігається між сеансами.</p><h2 id="графіки" tabindex="-1">Графіки <a class="header-anchor" href="#графіки" aria-label="Permalink to &quot;Графіки&quot;">​</a></h2><h3 id="панелі" tabindex="-1">Панелі <a class="header-anchor" href="#панелі" aria-label="Permalink to &quot;Панелі&quot;">​</a></h3><p>Analyzer відкривається з чотирма панелями графіків на <strong>5хв, 15хв, 1г і 4г</strong>. Це відправна точка, а не фіксована розкладка:</p><ul><li><strong>Add chart</strong> додає панель, максимум до <strong>8</strong>.</li><li><strong>Close chart</strong> прибирає одну, мінімум до <strong>1</strong>.</li><li>Кожна панель має власний випадний список таймфреймів: <code>1m</code>, <code>5m</code>, <code>15m</code>, <code>30m</code>, <code>1h</code>, <code>4h</code>, <code>1d</code>, <code>1w</code>.</li></ul><p>Ваша розкладка панелей і таймфрейм кожної з них зберігаються, тож вікно повертається таким, яким ви його лишили.</p><h3 id="історія" tabindex="-1">Історія <a class="header-anchor" href="#історія" aria-label="Permalink to &quot;Історія&quot;">​</a></h3><p>Прокручуйте графік вліво, щоб автоматично підвантажувати старіші свічки партіями — настільки далеко, наскільки їх надає біржа.</p><h3 id="повнии-екран" tabindex="-1">Повний екран <a class="header-anchor" href="#повнии-екран" aria-label="Permalink to &quot;Повний екран&quot;">​</a></h3><p>Кожна панель має кнопку розгортання на весь екран. У повноекранному режимі поруч із кожним таймфреймом у списку з&#39;являється зірочка — позначені таймфрейми показуються рядком швидкого доступу, спільним із повноекранними виглядами Knives і Monitor.</p><p>Щоб вийти, натисніть <kbd>Esc</kbd> або кнопку закриття.</p><h3 id="інструменти-рисування" tabindex="-1">Інструменти рисування <a class="header-anchor" href="#інструменти-рисування" aria-label="Permalink to &quot;Інструменти рисування&quot;">​</a></h3><p>На кожному графіку доступні п&#39;ять інструментів, кожен на своїй клавіші:</p><table tabindex="0"><thead><tr><th>Інструмент</th><th>Клавіша за замовчуванням</th></tr></thead><tbody><tr><td>Горизонтальний промінь</td><td><kbd>H</kbd></td></tr><tr><td>Лінія тренду</td><td><kbd>T</kbd></td></tr><tr><td>Прямокутник</td><td><kbd>B</kbd></td></tr><tr><td>Олівець</td><td><kbd>P</kbd></td></tr><tr><td>Зникаючий олівець</td><td><kbd>F</kbd></td></tr></tbody></table><p>Утримуйте <kbd>Ctrl</kbd> під час постановки точки, щоб прив&#39;язати її до найближчого максимуму чи мінімуму свічки.</p><p>Активний інструмент відстежується <strong>для кожної панелі окремо</strong>, тож можна малювати лінію тренду на одній панелі, поки інша лишається без інструмента.</p><p>Клавіші, колір рисунків і поведінка магніту налаштовуються — див. <a href="/manual/uk/customize/chart-colors.html">Графіки та рисування</a>.</p><h2 id="налаштування" tabindex="-1">Налаштування <a class="header-anchor" href="#налаштування" aria-label="Permalink to &quot;Налаштування&quot;">​</a></h2><p>Вкладка <strong>Analyzer</strong> у головному вікні не має налаштувань. У ній лише кнопка <strong>Open Window</strong> і розділ приміток.</p><h3 id="відомі-проблеми" tabindex="-1">Відомі проблеми <a class="header-anchor" href="#відомі-проблеми" aria-label="Permalink to &quot;Відомі проблеми&quot;">​</a></h3><p>Вкладка повідомляє про одне відоме обмеження, цитата із застосунку:</p><blockquote><p>Графіки Gate.io завантажуються довше, ніж на інших біржах. Це відома проблема, над виправленням ведеться робота.</p></blockquote><h2 id="пов-язане" tabindex="-1">Пов&#39;язане <a class="header-anchor" href="#пов-язане" aria-label="Permalink to &quot;Пов&#39;язане&quot;">​</a></h2><ul><li><a href="/manual/uk/customize/chart-colors.html">Графіки та рисування</a> — кольори свічок, колір рисунків, клавіші інструментів, магніт</li><li><a href="/manual/uk/tools/monitor.html">Monitor</a> — ранжований сканер; його картки теж відкривають повноекранні графіки з тими самими інструментами рисування</li><li><a href="/manual/uk/customize/majors.html">Шар мажорів</a> — великі угоди, кластери обсягу та ліквідації на будь-якій панелі</li></ul>',45))])}const f=e(h,[["render",c]]);export{q as __pageData,f as default};
